import{_ as s,a0 as r,w as p,s as d,I as l,x as t,a1 as a,A as o,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"netdev 第二天：從網絡代碼中移除“儘可能快”這個目標 | LCTT x X-CMD","titleTemplate":false,"description":"netdev 第二天：從網絡代碼中移除“儘可能快”這個目標 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"netdev 第二天：從網絡代碼中移除“儘可能快”這個目標 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"netdev 第二天：從網絡代碼中移除“儘可能快”這個目標 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180712 netdev day 2 moving away from as fast as possible in networking code","title":"netdev 第二天：從網絡代碼中移除“儘可能快”這個目標","tag":"201808","desc":""},"relativePath":"201808/20180712 netdev day 2 moving away from as fast as possible in networking code.md","filePath":"[post].md"}'),u={name:"201808/20180712 netdev day 2 moving away from as fast as possible in networking code.md"};function f(b,n,m,x,T,g){const i=r("Link");return p(),d("div",null,[n[33]||(n[33]=l("h1",{id:"netdev-第二天-從網絡代碼中移除-儘可能快-這個目標",tabindex:"-1"},[t("netdev 第二天：從網絡代碼中移除“儘可能快”這個目標 "),l("a",{class:"header-anchor",href:"#netdev-第二天-從網絡代碼中移除-儘可能快-這個目標","aria-label":"Permalink to “netdev 第二天：從網絡代碼中移除“儘可能快”這個目標”"},"​")],-1)),l("p",null,[n[1]||(n[1]=t("嗨！今天是 netdev 會議的第 2 天，我只參加了早上的會議，但它_非常有趣_。今早會議的主角是 ",-1)),a(i,{href:"https://en.wikipedia.org/wiki/Van_Jacobson"},{default:o(()=>[...n[0]||(n[0]=[t("Van Jacobson",-1)])]),_:1}),n[2]||(n[2]=t(" 給出的一場名為 “從儘可能快中變化：教網卡以時間”的演講，它的主題是關於互聯網中擁塞控制的未來！！！",-1))]),n[34]||(n[34]=l("p",null,"下面我將嘗試着對我從這次演講中學到的東西做總結，我幾乎肯定下面的內容有些錯誤，但不管怎樣，讓我們開始吧！",-1)),n[35]||(n[35]=l("p",null,"這次演講是關於互聯網是如何從 1988 開始改變的，為什麼現在我們需要新的算法，以及我們可以怎樣改變 Linux 的網絡棧來更容易地實現這些算法。",-1)),n[36]||(n[36]=l("h3",{id:"什麼是擁塞控制",tabindex:"-1"},[t("什麼是擁塞控制？ "),l("a",{class:"header-anchor",href:"#什麼是擁塞控制","aria-label":"Permalink to “什麼是擁塞控制？”"},"​")],-1)),n[37]||(n[37]=l("p",null,"在網絡上的任何成員總是無時無刻地發送信息包，而在互聯網上的連接之間有着極其不同的速度（某些相比其他極其緩慢），而有時候它們將被塞滿！當互聯網的一個設備以超過它能處理的速率接收信息包時，它將丟棄某些信息包。",-1)),n[38]||(n[38]=l("p",null,"你所能想像的最天真的發送信息包方式是：",-1)),n[39]||(n[39]=l("ol",null,[l("li",null,"將你必須發送的信息包一次性發送完。"),l("li",null,"假如你發現其中有的信息包被丟棄了，就馬上重新發送這些包。")],-1)),l("p",null,[n[4]||(n[4]=t("結果表明假如你按照上面的思路來實現 TCP，互聯網將會崩潰並停止運轉。我們知道它會崩潰是因為在 1986 年確實發生了崩潰的現象。為了解決這個問題，專家發明了擁塞控制算法 —— 描述如何避免互聯網的崩潰的原始論文是 Van Jacobson 於 1988 年發表的 ",-1)),a(i,{href:"https://cs162.eecs.berkeley.edu/static/readings/jacobson-congestion.pdf"},{default:o(()=>[...n[3]||(n[3]=[t("擁塞避免與控制",-1)])]),_:1}),n[5]||(n[5]=t("（30 年前！）。",-1))]),n[40]||(n[40]=l("h3",{id:"從-1988-年後互聯網發生了什麼改變",tabindex:"-1"},[t("從 1988 年後互聯網發生了什麼改變？ "),l("a",{class:"header-anchor",href:"#從-1988-年後互聯網發生了什麼改變","aria-label":"Permalink to “從 1988 年後互聯網發生了什麼改變？”"},"​")],-1)),n[41]||(n[41]=l("p",null,"在演講中，Van Jacobson 説互聯網的這些已經發生了改變：在以前的互聯網上，交換機可能總是擁有比服務器更快的網卡，所以這些位於互聯網中間層的服務器也可能比客户端更快，並且並不能對客户端發送信息包的速率有多大影響。",-1)),n[42]||(n[42]=l("p",null,"很顯然今天已經不是這樣的了！眾所周知，今天的計算機相比於 5 年前的計算機在速度上並沒有多大的提升（我們遇到了某些有關光速的問題）。所以我想路由器上的大型交換機並不會在速度上大幅領先於數據中心裏服務器上的網卡。",-1)),l("p",null,[n[7]||(n[7]=t("這聽起來有些糟糕，因為這意味着客户端更容易在中間層的連接中達到飽和，而這將導致互聯網變慢（而且 ",-1)),a(i,{href:"https://apenwarr.ca/log/?m=201101#10"},{default:o(()=>[...n[6]||(n[6]=[t("緩衝膨脹",-1)])]),_:1}),n[8]||(n[8]=t(" 將帶來更高的延遲）。",-1))]),n[43]||(n[43]=e('<p>所以為了提高互聯網的性能且不讓每個路由上的任務隊列都達到飽和，客户端需要表現得更好並且在發送信息包的時候慢一點。</p><h3 id="以更慢的速率發送更多的信息包以達到更好的性能" tabindex="-1">以更慢的速率發送更多的信息包以達到更好的性能 <a class="header-anchor" href="#以更慢的速率發送更多的信息包以達到更好的性能" aria-label="Permalink to “以更慢的速率發送更多的信息包以達到更好的性能”">​</a></h3><p>下面的結論真的讓我非常意外 —— 以更慢的速率發送信息包實際上可能會帶來更好的性能（即便你是在整個傳輸過程中，這樣做的唯一的人），下面是原因：</p><p>假設你打算發送 10MB 的數據，在你和你需要連接的客户端之間有一箇中間層，並且它的傳輸速率_非常低_，例如 1MB/s。假設你可以辨別這個慢連接（或者更多的後續中間層）的速度，那麼你有 2 個選擇：</p><ol><li>一次性將這 10MB 的數據發送完，然後看看會發生什麼。</li><li>減慢速率使得你能夠以 1MB/s 的速率傳給它。</li></ol><p>現在，無論你選擇何種方式，你可能都會發生丟包的現象。所以這樣看起來，你可能需要選擇一次性發送所有的信息包這種方式，對吧？不！！實際上在你的數據流的中間環節丟包要比在你的數據流的最後丟包要好得多。假如在中間環節有些包被丟棄了，你需要送往的那個客户端可以察覺到這個事情，然後再告訴你，這樣你就可以再次發送那些被丟棄的包，這樣便沒有多大的損失。但假如信息包在最末端被丟棄，那麼客户端將完全沒有辦法知道你一次性發送了所有的信息包！所以基本上在某個時刻被丟棄的包沒有讓你收到 ACK 信號時，你需要啓用超時機制，並且還得重新發送它們。而超時往往意味着需要花費很長時間！</p><p>所以為什麼以更慢的速率發送數據會更好呢？假如你發送數據的速率快於連接中的瓶頸，這時所有的信息包將會在某個地方堆積成一個隊列，這個隊列將會被塞滿，然後在你的數據流的最末端的信息包將會被丟棄。並且像我們剛才解釋的那樣，處於數據流最後面的信息包很有可能丟棄！所以相比於最初以合適的速率發送信息包，一次性發送它們將會觸發超時機制，發送 10MB 的數據將會花費更長的時間。</p><p>我認為這非常酷，因為這個過程並不需要與互聯網中的其他人合作 —— 即便其他的所有人都已非常快的速率傳送他們的信息包，對你來説以合適的速率（中間層的瓶頸速率）傳送你自己的信息包_仍然_更有優勢。</p><h3 id="如何辨別發送數據的合適速率-bbr" tabindex="-1">如何辨別發送數據的合適速率：BBR！ <a class="header-anchor" href="#如何辨別發送數據的合適速率-bbr" aria-label="Permalink to “如何辨別發送數據的合適速率：BBR！”">​</a></h3>',9)),l("p",null,[n[11]||(n[11]=t("在上面我説過：“假設你可以辨別出位於你的終端和服務器之間慢連接的速率……”，那麼如何做到呢？來自 Google（Jacobson 工作的地方）的某些專家已經提出了一個算法來估計瓶頸的速率！它叫做 BBR，由於本次的分享已經很長了，所以這裏不做具體介紹，但你可以參考 ",-1)),a(i,{href:"https://queue.acm.org/detail.cfm?id=3022184"},{default:o(()=>[...n[9]||(n[9]=[t("BBR：基於擁塞的擁塞控制",-1)])]),_:1}),n[12]||(n[12]=t(" 和 ",-1)),a(i,{href:"https://blog.acolyer.org/2017/03/31/bbr-congestion-based-congestion-control/"},{default:o(()=>[...n[10]||(n[10]=[t("來自晨讀論文的總結",-1)])]),_:1}),n[13]||(n[13]=t(" 這兩處鏈接。",-1))]),l("p",null,[n[15]||(n[15]=t("（另外，",-1)),a(i,{href:"https://blog.acolyer.org/"},{default:o(()=>[...n[14]||(n[14]=[t("https://blog.acolyer.org",-1)])]),_:1}),n[16]||(n[16]=t(" 的每日“晨讀論文”總結基本上是我學習和理解計算機科學論文的唯一方式，它有可能是整個互聯網上最好的Blog之一！）",-1))]),n[44]||(n[44]=e('<h3 id="網絡代碼被設計為運行得-儘可能快" tabindex="-1">網絡代碼被設計為運行得“儘可能快“ <a class="header-anchor" href="#網絡代碼被設計為運行得-儘可能快" aria-label="Permalink to “網絡代碼被設計為運行得“儘可能快“”">​</a></h3><p>所以，假設我們相信我們想以一個更慢的速率（例如以我們連接中的瓶頸速率）來傳輸數據。這很好，但網絡軟件並不是被設計為以一個可控速率來傳輸數據的！下面是我所理解的大多數網絡軟件怎麼做的：</p><ol><li>現在有一個隊列的信息包來臨；</li><li>然後軟件讀取隊列並儘可能快地發送信息包；</li><li>就這樣，沒有了。</li></ol><p>這個過程非常呆板 —— 假設我以一個非常快的速率發送信息包，而另一端的連接卻非常慢。假如我所擁有的就是一個放置所有信息包的隊列，當我實際要發送數據時，我並沒有辦法來控制這個發送過程，所以我便不能減慢這個隊列傳輸的速率。</p><h3 id="一個更好的方式-給每個信息包一個-最早的出發時間" tabindex="-1">一個更好的方式：給每個信息包一個“最早的出發時間” <a class="header-anchor" href="#一個更好的方式-給每個信息包一個-最早的出發時間" aria-label="Permalink to “一個更好的方式：給每個信息包一個“最早的出發時間””">​</a></h3><p>BBR 協議將會修改 Linux 內核中 skb 的數據結構（這個數據結構被用來表達網絡信息包），使得它有一個時間戳，這個時間戳代表着這個信息包應該被髮送出去的最早時間。</p><p>對於 Linux 網絡棧我不知道更多的詳情了，但對於我來説，這個協議最有趣的地方是這個改動並不是一個非常大的改動！它只是添加了一個額外的時間戳而已。</p><h3 id="用時間輪盤替換隊列" tabindex="-1">用時間輪盤替換隊列！！！ <a class="header-anchor" href="#用時間輪盤替換隊列" aria-label="Permalink to “用時間輪盤替換隊列！！！”">​</a></h3><p>一旦我們將時間戳打到這些信息包上，我們怎樣在合適的時間將它們發送出去呢？使用_時間輪盤_！</p>',9)),l("p",null,[n[18]||(n[18]=t("在前不久的“我們喜愛的論文”活動中（這是關於這次聚會描述的",-1)),a(i,{href:"https://www.meetup.com/Papers-We-Love-Montreal/events/235100825/"},{default:o(()=>[...n[17]||(n[17]=[t("某些好的鏈接",-1)])]),_:1}),n[19]||(n[19]=t("），有一個演講談論了關於時間輪盤的話題。時間輪盤是一類用來指導 Linux 的進程調度器決定何時運行進程的算法。",-1))]),n[45]||(n[45]=e('<p>Van Jacobson 説道：時間輪盤實際上比隊列調度工作得更好 —— 它們都提供常數時間的操作，但因為某些緩存機制，時間輪盤的常數要更小一些。我真的沒有太明白這裏他説的關於性能的解釋。</p><p>他説道：關於時間輪盤的一個關鍵點是你可以很輕鬆地用時間輪盤實現一個隊列（但反之不能！）—— 假如每次你增加一個新的信息包，在最開始你説我想讓它_現在_就被髮送走，很顯然這樣你就可以得到一個隊列了。而這個時間輪盤方法是向後兼容的，它使得你可以更容易地實現某些更加複雜的對流量非常敏感的算法，例如讓你針對不同的信息包以不同的速率去發送它們。</p><h3 id="或許我們可以通過改善-linux-來修復互聯網" tabindex="-1">或許我們可以通過改善 Linux 來修復互聯網！ <a class="header-anchor" href="#或許我們可以通過改善-linux-來修復互聯網" aria-label="Permalink to “或許我們可以通過改善 Linux 來修復互聯網！”">​</a></h3><p>對於任何影響到整個互聯網規模的問題，最為棘手的問題是當你要做出改善時，例如改變互聯網協議的實現，你需要面對各種不同的設備。你要面對 Linux 的機器、BSD 的機器、Windows 的機器、各種各樣的手機、瞻博或者思科的路由器以及數量繁多的其他設備！</p><p>但是在網絡環境中 Linux 處於某種有趣的位置上！</p><ul><li>Android 手機運行着 Linux</li><li>大多數的消費級 WiFi 路由器運行着 Linux</li><li>無數的服務器運行着 Linux</li></ul><p>所以在任何給定的網絡連接中，實際上很有可能在兩端都有一台 Linux 機器（例如一個 Linux 服務器、或者一個 Linux 路由器、一台 Android 設備）。</p><p>所以重點是假如你想大幅改善互聯網上的擁塞狀況，只需要改變 Linux 網絡棧就會大所不同（或許 iOS 網絡棧也是類似的）。這也就是為什麼在本次的 Linux 網絡會議上有這樣的一個演講！</p><h3 id="互聯網仍在改變-酷" tabindex="-1">互聯網仍在改變！酷！ <a class="header-anchor" href="#互聯網仍在改變-酷" aria-label="Permalink to “互聯網仍在改變！酷！”">​</a></h3><p>通常我以為 TCP/IP 仍然是上世紀 80 年代的東西，所以當從這些專家口中聽説這些我們正在設計的網路協議仍然有許多嚴重的問題時，真的是非常有趣，並且聽説現在有不同的方式來設計它們。</p><p>當然也確實是這樣 —— 網絡硬件以及和速度相關的任何設備，以及人們使用網絡來乾的各種事情（例如觀看 Netflix 的節目）等等，一直都在隨着時間發生着改變，所以正因為這樣，我們需要為 2018 年的互聯網而不是為 1988 年的互聯網設計我們不同的算法。</p><hr>',12)),l("p",null,[n[21]||(n[21]=t("via: ",-1)),a(i,{href:"https://jvns.ca/blog/2018/07/12/netdev-day-2--moving-away-from--as-fast-as-possible/"},{default:o(()=>[...n[20]||(n[20]=[t("https://jvns.ca/blog/2018/07/12/netdev-day-2--moving-away-from--as-fast-as-possible/",-1)])]),_:1})]),l("p",null,[n[25]||(n[25]=t("作者：",-1)),a(i,{href:"https://jvns.ca/about"},{default:o(()=>[...n[22]||(n[22]=[t("Julia Evans",-1)])]),_:1}),n[26]||(n[26]=t(" 譯者：",-1)),a(i,{href:"https://github.com/FSSlc"},{default:o(()=>[...n[23]||(n[23]=[t("FSSlc",-1)])]),_:1}),n[27]||(n[27]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...n[24]||(n[24]=[t("wxy",-1)])]),_:1})]),l("p",null,[n[30]||(n[30]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[28]||(n[28]=[t("LCTT",-1)])]),_:1}),n[31]||(n[31]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:o(()=>[...n[29]||(n[29]=[t("Linux中國",-1)])]),_:1}),n[32]||(n[32]=t(" 榮譽推出",-1))])])}const P=s(u,[["render",f]]);export{C as __pageData,P as default};
